-- AAYAM Production Database Seed Script for Supabase PostgreSQL
-- Preserves all 77 records across 8 relational tables with 100% integrity
-- Generated automatically

BEGIN;


CREATE TABLE IF NOT EXISTS users (
	id VARCHAR(64) NOT NULL PRIMARY KEY, 
	username VARCHAR(100) NOT NULL, 
	email VARCHAR(255) NOT NULL, 
	full_name VARCHAR(255) NOT NULL, 
	password_hash VARCHAR(255) NOT NULL, 
	role VARCHAR(50) NOT NULL, 
	is_active BOOLEAN NOT NULL, 
	created_at TIMESTAMP WITHOUT TIME ZONE, 
	updated_at TIMESTAMP WITHOUT TIME ZONE
);

CREATE TABLE IF NOT EXISTS assets (
	id VARCHAR(64) NOT NULL PRIMARY KEY, 
	name VARCHAR(255) NOT NULL, 
	category VARCHAR(100) NOT NULL, 
	district VARCHAR(100) NOT NULL, 
	state VARCHAR(100) NOT NULL, 
	latitude FLOAT NOT NULL, 
	longitude FLOAT NOT NULL, 
	construction_year INTEGER, 
	status VARCHAR(50) NOT NULL, 
	ownership_authority VARCHAR(200), 
	data_source VARCHAR(255) NOT NULL, 
	risk_score FLOAT NOT NULL, 
	risk_level VARCHAR(30) NOT NULL, 
	health_index FLOAT NOT NULL, 
	last_inspection_date VARCHAR(30), 
	flagged_reasons TEXT, 
	description TEXT, 
	created_at TIMESTAMP WITHOUT TIME ZONE, 
	updated_at TIMESTAMP WITHOUT TIME ZONE
);

CREATE TABLE IF NOT EXISTS inspections (
	id VARCHAR(64) NOT NULL PRIMARY KEY, 
	asset_id VARCHAR(64) NOT NULL REFERENCES assets(id), 
	inspection_date VARCHAR(30) NOT NULL, 
	inspection_type VARCHAR(100) NOT NULL, 
	findings TEXT NOT NULL, 
	recommended_action TEXT, 
	actual_action_taken TEXT, 
	responsible_user VARCHAR(100), 
	status VARCHAR(50) NOT NULL, 
	evidence_references TEXT, 
	verification_notes TEXT, 
	verification_date VARCHAR(30), 
	verification_outcome VARCHAR(50), 
	created_at TIMESTAMP WITHOUT TIME ZONE, 
	updated_at TIMESTAMP WITHOUT TIME ZONE
);

CREATE TABLE IF NOT EXISTS asset_media (
	id VARCHAR(64) NOT NULL PRIMARY KEY, 
	asset_id VARCHAR(64) NOT NULL REFERENCES assets(id), 
	inspection_id VARCHAR(64) REFERENCES inspections(id) ON DELETE SET NULL, 
	file_name VARCHAR(255) NOT NULL, 
	file_path VARCHAR(255) NOT NULL, 
	caption VARCHAR(255) NOT NULL, 
	category VARCHAR(50) NOT NULL, 
	uploader_name VARCHAR(100) NOT NULL, 
	captured_at VARCHAR(30), 
	verification_status VARCHAR(30) NOT NULL, 
	created_at TIMESTAMP WITHOUT TIME ZONE
);

CREATE TABLE IF NOT EXISTS evidence_sources (
	id VARCHAR(64) NOT NULL PRIMARY KEY, 
	asset_id VARCHAR(64) NOT NULL REFERENCES assets(id), 
	title VARCHAR(255) NOT NULL, 
	source_type VARCHAR(50) NOT NULL, 
	provider VARCHAR(150) NOT NULL, 
	document_name VARCHAR(255), 
	page_or_paragraph VARCHAR(50), 
	excerpt TEXT, 
	verification_status VARCHAR(30) NOT NULL, 
	publication_date VARCHAR(30), 
	created_at TIMESTAMP WITHOUT TIME ZONE
);

CREATE TABLE IF NOT EXISTS ai_intelligence_runs (
	id VARCHAR(64) NOT NULL PRIMARY KEY, 
	asset_id VARCHAR(64) NOT NULL REFERENCES assets(id), 
	model_used VARCHAR(100) NOT NULL, 
	status VARCHAR(50) NOT NULL, 
	overall_condition_summary TEXT, 
	structural_summary TEXT, 
	environmental_summary TEXT, 
	compliance_summary TEXT, 
	operational_summary TEXT, 
	predictive_summary TEXT, 
	predictive_data_warning TEXT, 
	data_limitations TEXT, 
	conflicting_evidence TEXT, 
	prompt_tokens INTEGER NOT NULL, 
	completion_tokens INTEGER NOT NULL, 
	total_tokens INTEGER NOT NULL, 
	estimated_cost_usd FLOAT NOT NULL, 
	latency_ms INTEGER NOT NULL, 
	created_at TIMESTAMP WITHOUT TIME ZONE
);

CREATE TABLE IF NOT EXISTS asset_findings (
	id VARCHAR(64) NOT NULL PRIMARY KEY, 
	asset_id VARCHAR(64) NOT NULL REFERENCES assets(id), 
	title VARCHAR(200) NOT NULL, 
	plain_explanation TEXT NOT NULL, 
	technical_explanation TEXT NOT NULL, 
	severity VARCHAR(30) NOT NULL, 
	affected_component VARCHAR(150) NOT NULL, 
	supporting_evidence VARCHAR(255), 
	date_identified VARCHAR(30) NOT NULL, 
	verification_status VARCHAR(50) NOT NULL, 
	recommended_action TEXT NOT NULL, 
	resolution_status VARCHAR(50) NOT NULL, 
	intelligence_category VARCHAR(50) NOT NULL, 
	evidence_classification VARCHAR(50) NOT NULL, 
	confidence_level VARCHAR(20) NOT NULL, 
	source_document VARCHAR(255), 
	page_number INTEGER, 
	image_reference VARCHAR(255), 
	reviewed_by VARCHAR(100), 
	reviewed_at VARCHAR(50), 
	review_decision_notes TEXT, 
	ai_generated BOOLEAN NOT NULL, 
	run_id VARCHAR(64) REFERENCES ai_intelligence_runs(id) ON DELETE SET NULL, 
	exact_location VARCHAR(200), 
	severity_level INTEGER, 
	potential_consequences TEXT, 
	immediate_action TEXT, 
	further_investigation TEXT, 
	responsible_discipline VARCHAR(150), 
	action_stage VARCHAR(30), 
	timeframe VARCHAR(50), 
	approval_required VARCHAR(150), 
	risk_contribution_pts FLOAT, 
	created_at TIMESTAMP WITHOUT TIME ZONE
);

CREATE TABLE IF NOT EXISTS ai_conversation_messages (
	id VARCHAR(64) NOT NULL PRIMARY KEY, 
	asset_id VARCHAR(64) REFERENCES assets(id) ON DELETE SET NULL, 
	user_id VARCHAR(64) REFERENCES users(id) ON DELETE SET NULL, 
	question TEXT NOT NULL, 
	answer TEXT NOT NULL, 
	citations_json TEXT, 
	evidence_json TEXT, 
	model_used VARCHAR(100) NOT NULL, 
	pipeline_type VARCHAR(50) NOT NULL, 
	tokens_used INTEGER NOT NULL, 
	created_at TIMESTAMP WITHOUT TIME ZONE
);

