INSERT INTO asset_findings (id, asset_id, title, plain_explanation, technical_explanation, severity, affected_component, supporting_evidence, date_identified, verification_status, recommended_action, resolution_status, created_at, intelligence_category, evidence_classification, confidence_level, source_document, page_number, image_reference, reviewed_by, reviewed_at, review_decision_notes, ai_generated, run_id, exact_location, severity_level, potential_consequences, immediate_action, further_investigation, responsible_discipline, action_stage, timeframe, approval_required, risk_contribution_pts) VALUES ('FND-001-A', 'ASSET-BRG-001', 'Sub-Surface Scour Hole Depth of 2.40m at Pier 4', 'River currents and tidal flows have eroded the sand and soil directly beneath the concrete bridge pier, weakening the foundation support.', 'Sonar bathymetry confirmed localized scour depression of 2.4m adjacent to Pier 4 pile cap, exceeding permissible geotechnical limits.', 'Critical', 'Pier 4 Foundation & Pile Cap', 'Mandovi_Bridge_Pier_Scour_Audit_2023.pdf', '2023-11-14', 'Verified', 'Deploy emergency rip-rap heavy boulder dumping around Pier 4; restrict commercial vehicle speed to 30 km/h.', 'Intervention Underway', '2026-10-24 10:28:44.390446', 'Structural', 'Documented', 'High', NULL, NULL, NULL, 'Chief Infrastructure Engineer (Admin) (@admin)', '2026-11-03 08:29 UTC', 'Verified on-site', 0, NULL, NULL, 3, NULL, NULL, NULL, NULL, 'Stage A', NULL, NULL, 0.0) ON CONFLICT (id) DO NOTHING;
INSERT INTO asset_findings (id, asset_id, title, plain_explanation, technical_explanation, severity, affected_component, supporting_evidence, date_identified, verification_status, recommended_action, resolution_status, created_at, intelligence_category, evidence_classification, confidence_level, source_document, page_number, image_reference, reviewed_by, reviewed_at, review_decision_notes, ai_generated, run_id, exact_location, severity_level, potential_consequences, immediate_action, further_investigation, responsible_discipline, action_stage, timeframe, approval_required, risk_contribution_pts) VALUES ('FND-001-B', 'ASSET-BRG-001', 'Expansion Joint EJ-4 Elastomeric Delamination (>48mm Gap)', 'The flexible expansion joint between bridge spans has torn and widened, allowing rainwater and salt into the bridge structure.', 'Joint opening measured at 48.2mm (design limit: 25.0mm). Neoprene gland delaminated; chloride water ingress accelerating tendon corrosion.', 'High', 'Expansion Joint EJ-4 (Span 3-4)', 'mandovi_expansion_joint.svg', '2023-11-14', 'Verified by Field Audit', 'Complete replacement with modular elastomeric strip seal joint.', 'Open', '2026-10-24 10:28:44.390448', 'Structural', 'Documented', 'High', NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, 3, NULL, NULL, NULL, NULL, 'Stage A', NULL, NULL, 0.0) ON CONFLICT (id) DO NOTHING;
INSERT INTO asset_findings (id, asset_id, title, plain_explanation, technical_explanation, severity, affected_component, supporting_evidence, date_identified, verification_status, recommended_action, resolution_status, created_at, intelligence_category, evidence_classification, confidence_level, source_document, page_number, image_reference, reviewed_by, reviewed_at, review_decision_notes, ai_generated, run_id, exact_location, severity_level, potential_consequences, immediate_action, further_investigation, responsible_discipline, action_stage, timeframe, approval_required, risk_contribution_pts) VALUES ('FND-002-A', 'ASSET-WTP-002', 'Pump Motor #3 Radial Vibration Spike (7.82 mm/s RMS)', 'The primary water pump motor is vibrating at nearly double the safe limit, threatening unexpected equipment shutdown.', 'Tri-axial vibration velocity exceeds ISO 10816 Class III standard (4.5 mm/s limit). Spectrum indicates impeller cavitation and dynamic unbalance.', 'High', 'Raw Water High-Lift Pump Train #3', 'Chambal_WTP_Pump_Vibration_Report_2024.txt', '2024-03-02', 'Verified by Field Audit', 'Isolate pump train, re-balance bronze impeller, and replace drive coupling elastomeric inserts.', 'Open', '2026-10-24 10:28:44.390448', 'Structural', 'Documented', 'High', NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, 3, NULL, NULL, NULL, NULL, 'Stage A', NULL, NULL, 0.0) ON CONFLICT (id) DO NOTHING;
INSERT INTO asset_findings (id, asset_id, title, plain_explanation, technical_explanation, severity, affected_component, supporting_evidence, date_identified, verification_status, recommended_action, resolution_status, created_at, intelligence_category, evidence_classification, confidence_level, source_document, page_number, image_reference, reviewed_by, reviewed_at, review_decision_notes, ai_generated, run_id, exact_location, severity_level, potential_consequences, immediate_action, further_investigation, responsible_discipline, action_stage, timeframe, approval_required, risk_contribution_pts) VALUES ('FND-003-A', 'ASSET-HWY-003', 'Culvert Barrel Silt Deposition Exceeding 60% Hydraulic Cross-Section', 'Mud and gravel from mountain rains have blocked more than half the drainage tunnel under the highway, creating flood risks.', 'Heavy silt wedge in 2.5m x 2.0m box culvert barrel creates upstream hydraulic head surcharge, risking roadway slope washout.', 'Moderate', 'Culvert Box Barrel & Upstream Wingwall', 'Western_Ghats_Culvert_Hydrology_2024.txt', '2024-05-18', 'Verified by Field Audit', 'Execute mechanical desilting and construct upstream boulder debris arrestor trap.', 'Open', '2026-10-24 10:28:44.390448', 'Structural', 'Documented', 'High', NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, 3, NULL, NULL, NULL, NULL, 'Stage A', NULL, NULL, 0.0) ON CONFLICT (id) DO NOTHING;
INSERT INTO asset_findings (id, asset_id, title, plain_explanation, technical_explanation, severity, affected_component, supporting_evidence, date_identified, verification_status, recommended_action, resolution_status, created_at, intelligence_category, evidence_classification, confidence_level, source_document, page_number, image_reference, reviewed_by, reviewed_at, review_decision_notes, ai_generated, run_id, exact_location, severity_level, potential_consequences, immediate_action, further_investigation, responsible_discipline, action_stage, timeframe, approval_required, risk_contribution_pts) VALUES ('FND-004-A', 'ASSET-CNL-004', 'Lock Gate #12 Sealing Operability Verified After Maintenance', 'Canal gate seals were replaced and tested under full water pressure, with zero leakage confirmed.', 'Pre-monsoon hydrostatic flow test verified zero bypass leakage under full 4.2m head pressure. Gate #12 certified operational.', 'Low', 'Lock Gate #12 Seals & Hydraulic Winch', 'Field Verification Certificate #AP-WRD-2024-441', '2024-08-10', 'Verified by Field Audit', 'Continue routine quarterly grease lubrication and monthly visual inspection.', 'Resolved & Certified', '2026-10-24 10:28:44.390449', 'Structural', 'Documented', 'High', NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, 3, NULL, NULL, NULL, NULL, 'Stage A', NULL, NULL, 0.0) ON CONFLICT (id) DO NOTHING;
INSERT INTO asset_findings (id, asset_id, title, plain_explanation, technical_explanation, severity, affected_component, supporting_evidence, date_identified, verification_status, recommended_action, resolution_status, created_at, intelligence_category, evidence_classification, confidence_level, source_document, page_number, image_reference, reviewed_by, reviewed_at, review_decision_notes, ai_generated, run_id, exact_location, severity_level, potential_consequences, immediate_action, further_investigation, responsible_discipline, action_stage, timeframe, approval_required, risk_contribution_pts) VALUES ('FND-008-A', 'ASSET-FLY-008', 'Elastomeric Bearing Pad Extrusion on Pier P-12', 'The rubber shock absorber between the flyover deck and the concrete pillar is squishing out under heavy bus traffic.', 'Neoprene bearing pad extruded by 18mm beyond steel sole plate; severe bulging and micro-cracking observed under transit vibration.', 'High', 'Pier P-12 Bearing Assembly', 'DDA_Flyover_Inspection_RampB_2024.txt', '2024-01-30', 'Verified by Field Audit', 'Erect temporary hydraulic jacking towers, relieve span dead load, and replace bearing pad.', 'Open', '2026-10-24 10:28:44.390449', 'Structural', 'Documented', 'High', NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, 3, NULL, NULL, NULL, NULL, 'Stage A', NULL, NULL, 0.0) ON CONFLICT (id) DO NOTHING;
